const pool = require('../db');

async function logAudit(req, action, meta = {}) {
  try {
    const uid = req.user?.id || req.user?.userId || null;
    await pool.query(
      `INSERT INTO audit_log (user_id, action, path, method, ip, meta, created_at)
        VALUES ($1,$2,$3,$4,$5,$6,NOW())`,
      [uid, action, req.originalUrl, req.method, req.ip, JSON.stringify(meta)]
    );
  } catch (e) {
    console.error('Audit log error:', e);
  }
}

module.exports = { logAudit };

const client = await pool.connect();
try {
  await client.query('BEGIN');
  // ... your INSERT/UPDATE/DELETE calls
  await client.query('COMMIT');
  await logAudit(req, 'ENTITY_UPDATE', { id });
} catch (e) {
  await client.query('ROLLBACK');
  throw e;
} finally {
  client.release();
}

// server/middleware/validation.js
const Joi = require('joi');

function validate(schema) {
  return (req, res, next) => {
    const src = req.method === 'GET' ? req.query : req.body; // adjust if you validate params too
    const { error, value } = schema.validate(src, { abortEarly: false, stripUnknown: true });
    if (error) {
      return res.status(400).json({
        error: 'Validation failed',
        details: error.details.map(d => ({ message: d.message, path: d.path })),
      });
    }
    if (req.method === 'GET') req.query = value; else req.body = value;
    next();
  };
}

module.exports = { validate };

// server/routes/someRouter.js
const express = require('express');
const router = express.Router();
const Joi = require('joi');
const { validate } = require('../middleware/validation');

const createSchema = Joi.object({
  name: Joi.string().min(2).max(120).required(),
  email: Joi.string().email().required(),
  count: Joi.number().integer().min(0).default(0),
});

router.post('/create', validate(createSchema), async (req, res) => {
  // safe, validated req.body here
  res.json({ success: true });
});

module.exports = router;

// server/routes/someRouter.js
const { body, validationResult } = require('express-validator');

router.post('/create',
  [
    body('name').isString().isLength({ min: 2, max: 120 }),
    body('email').isEmail(),
    body('count').optional().isInt({ min: 0 }),
  ],
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ error: 'Validation failed', details: errors.array() });
    next();
  },
  async (req, res) => {
    res.json({ success: true });
  }
);

