  await Model.create(data, { transaction: t });
  await Audit.create({ action: 'CREATE' }, { transaction: t });
});

// Knex
await knex.transaction(async (trx) => {
  await trx('items').insert(data);
  await trx('audit_log').insert({ action: 'CREATE' });
});

// src/App.jsx (inside a useEffect)
useEffect(() => {
  const update = () => localStorage.setItem('lastActivity', String(Date.now()));
  const check = setInterval(() => {
    const last = Number(localStorage.getItem('lastActivity') || 0);
    if (Date.now() - last > 15 * 60 * 1000) {
      localStorage.removeItem('token');
      localStorage.removeItem('lastActivity');
      navigate('/login');
    }
  }, 60 * 1000);

  window.addEventListener('mousemove', update);
  window.addEventListener('keydown', update);
  window.addEventListener('click', update);
  update();

  return () => {
    clearInterval(check);
    window.removeEventListener('mousemove', update);
    window.removeEventListener('keydown', update);
    window.removeEventListener('click', update);
  };
}, [navigate]);

